"""Independent float64 energy/gradient and declared diagonal-block reference."""
import numpy as np

def bulk_reference(x,data):
 x=np.asarray(x,dtype=float);pairs=data['springs'];diff=x[pairs[:,0]]-x[pairs[:,1]];length=np.maximum(np.linalg.norm(diff,axis=1),1e-8);rest=np.linalg.norm(data['x'][pairs[:,0]]-data['x'][pairs[:,1]],axis=1);k=data['k'];pair_force=k[:,None]*((rest-length)/length)[:,None]*diff;forces=np.zeros_like(x);np.add.at(forces,pairs[:,0],pair_force);np.add.at(forces,pairs[:,1],-pair_force);identity=np.eye(3);pair_h=k[:,None,None]*(identity-(rest/length)[:,None,None]*(identity-np.einsum('ni,nj->nij',diff,diff)/length[:,None,None]**2));h=np.zeros((len(x),3,3));np.add.at(h,pairs[:,0],pair_h);np.add.at(h,pairs[:,1],pair_h);spring_energy=float(np.sum(.5*k*(length-rest)**2));cells=data['cells'];q=x[cells];a=q[:,1]-q[:,0];b=q[:,2]-q[:,0];c=q[:,3]-q[:,0];V=data['volumes'];J=np.linalg.det(q[:,1:]-q[:,:1])/(6*V)
 if np.any(J<=.1):raise ValueError('Reference volume floor violated')
 gradients=np.stack([np.cross(b,c),np.cross(c,a),np.cross(a,b)],axis=1)/(6*V[:,None,None]);gradients=np.concatenate([-gradients.sum(1)[:,None],gradients],axis=1);active=J<.5;r=(J[active]-.1)/.4;first=(1-1/r)/.4;second=1/(.16*r*r);f=-10000*V[active,None,None]*first[:,None,None]*gradients[active];blocks=10000*V[active,None,None,None]*second[:,None,None,None]*np.einsum('nqi,nqj->nqij',gradients[active],gradients[active]);np.add.at(forces,cells[active].ravel(),f.reshape(-1,3));np.add.at(h,cells[active].ravel(),blocks.reshape(-1,3,3));barrier=float(np.sum(10000*V[active]*(r-1-np.log(r))));return dict(force=forces,blocks=h,energy_j=spring_energy+barrier,spring_energy_j=spring_energy,volume_energy_j=barrier,minimum_volume_ratio=float(J.min()))
